import java.util.*;

class NeighborSum {
  private final int[][] grid;
  private final Map<Integer, int[]> position = new HashMap<>();

  public NeighborSum(int[][] grid) {
    this.grid = grid;
    for (int r = 0; r < grid.length; r++)
      for (int c = 0; c < grid[0].length; c++) position.put(grid[r][c], new int[] {r, c});
  }

  public int adjacentSum(int value) {
    int[] p = position.get(value), sum = {0};
    int[][] d = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    for (int[] x : d) {
      int r = p[0] + x[0], c = p[1] + x[1];
      if (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length) sum[0] += grid[r][c];
    }
    return sum[0];
  }

  public int diagonalSum(int value) {
    int[] p = position.get(value);
    int result = 0;
    int[][] d = {{-1, -1}, {-1, 1}, {1, -1}, {1, 1}};
    for (int[] x : d) {
      int r = p[0] + x[0], c = p[1] + x[1];
      if (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length) result += grid[r][c];
    }
    return result;
  }
}
